// PalindromeChecker.javaclass PalindromeChecker {    // Attribute    String text;    // Constructor    PalindromeChecker(String text) {        this.text = text;    }    // Method to remove spaces and convert to lowercase manually    String cleanText() {        String result = "";        for (int i = 0; i < text.length(); i++) {            char ch = text.charAt(i);            if (ch != ' ') { // only ignore spaces                result += Character.toLowerCase(ch);            }        }        return result;    }    // Method to check if the text is a palindrome    boolean isPalindrome() {        String cleaned = cleanText();        int left = 0;        int right = cleaned.length() - 1;        while (left < right) {            if (cleaned.charAt(left) != cleaned.charAt(right)) {                return false;            }            left++;            right--;        }        return true;    }    // Method to display result    void displayResult() {        if (isPalindrome()) {            System.out.println("\"" + text + "\" is a palindrome.");        } else {            System.out.println("\"" + text + "\" is not a palindrome.");        }    }}// Main class to testpublic class PalindromeTest {    public static void main(String[] args) {        PalindromeChecker checker1 = new PalindromeChecker("Madam");        checker1.displayResult();        PalindromeChecker checker2 = new PalindromeChecker("Race car");        checker2.displayResult();        PalindromeChecker checker3 = new PalindromeChecker("Hello");        checker3.displayResult();    }}